{"command":"create","file_text":"import type pg from 'pg';
import { pool } from '../../../packages/database/src/pool.js';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  idempotency_key: string | null;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  max_attempts: number;
  last_error: string | null;
  available_at: Date;
  locked_by: string | null;
  locked_at: Date | null;
  lease_expires_at: Date | null;
  completed_at: Date | null;
  created_at: Date;
  updated_at: Date;
}

export interface ErasureRequestResponse {
  id: string;
  customerId: string;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export function formatErasureRequest(row: ErasureRequestRow): ErasureRequestResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error ?? null,
  };
}

export class ErasureRepository {
  async findById(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id = $1 AND id = $2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findByKey(client: pg.PoolClient, merchantId: string, idempotencyKey: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id = $1 AND idempotency_key = $2 FOR UPDATE`,
      [merchantId, idempotencyKey],
    );
    return result.rows[0];
  }

  async findByCustomer(client: pg.PoolClient, merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id = $1 AND customer_id = $2 FOR UPDATE`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async create(client: pg.PoolClient, merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id, customer_id, idempotency_key, status, attempts)
       VALUES($1, $2, $3, 'pending', 0)
       RETURNING *`,
      [merchantId, customerId, idempotencyKey],
    );
    return result.rows[0]!;
  }

  async resetFailedForRetry(client: pg.PoolClient, id: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status = 'pending', available_at = now(), updated_at = now()
       WHERE id = $1`,
      [id],
    );
  }

  async claim(workerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status = 'processing',
           locked_by = $1,
           locked_at = now(),
           lease_expires_at = now() + interval '60 seconds',
           updated_at = now()
       WHERE id = (
         SELECT id FROM customers.erasure_requests
         WHERE status IN ('pending', 'failed')
           AND available_at <= now()
         ORDER BY available_at, created_at
         FOR UPDATE SKIP LOCKED
         LIMIT 1
       )
       RETURNING *`,
      [workerId],
    );
    return result.rows[0];
  }

  async recoverExpiredLeases(): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status = 'pending',
           locked_by = NULL,
           locked_at = NULL,
           lease_expires_at = NULL,
           updated_at = now()
       WHERE status = 'processing'
         AND lease_expires_at <= now()`,
    );
  }

  async markFailed(id: string, errorCode: string, delaySeconds: number): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status = 'failed',
           last_error = $2,
           attempts = attempts + 1,
           locked_by = NULL,
           locked_at = NULL,
           lease_expires_at = NULL,
           available_at = now() + ($3 || ' seconds')::interval,
           updated_at = now()
       WHERE id = $1`,
      [id, errorCode, delaySeconds],
    );
  }

  async markCompleted(client: pg.PoolClient, id: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status = 'completed',
           completed_at = now(),
           updated_at = now(),
           locked_by = NULL,
           locked_at = NULL,
           lease_expires_at = NULL,
           last_error = NULL,
           attempts = attempts + 1
       WHERE id = $1`,
      [id],
    );
  }

  async cleanupDatabase(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    // 1. Redact customer identity in customers.customers
    await client.query(
      `UPDATE customers.customers
       SET email = 'deleted-' || id || '@deleted.payflow.test',
           external_reference = 'deleted-' || id,
           name = 'Deleted Customer',
           phone = NULL,
           metadata = '{}'::jsonb,
           status = 'deleted',
           updated_at = now(),
           version = version + 1
       WHERE merchant_id = $1 AND id = $2`,
      [merchantId, customerId],
    );

    // 2. Remove address, contact, payment method, and provider mapping records
    await client.query(`DELETE FROM customers.addresses WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.contacts WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.payment_method_refs WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.provider_customer_mappings WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
    await client.query(`DELETE FROM provider_sandbox.customers WHERE merchant_id = $1 AND payflow_customer_id = $2`, [merchantId, customerId]);

    // 3. Support messages and tickets
    await client.query(`DELETE FROM customers.support_messages WHERE merchant_id = $1 AND author_id = $2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.support_participants WHERE customer_id = $2`, [customerId]);
    await client.query(
      `DELETE FROM customers.support_tickets WHERE merchant_id = $1 AND id NOT IN (SELECT ticket_id FROM customers.support_participants)`,
      [merchantId],
    );
    await client.query(
      `DELETE FROM customers.support_messages WHERE merchant_id = $1 AND ticket_id NOT IN (SELECT id FROM customers.support_tickets)`,
      [merchantId],
    );

    // 4. Retained financial records: redact identifying personal details while keeping financial facts
    await client.query(
      `UPDATE payments.payment_intents
       SET description = NULL,
           customer_snapshot = jsonb_build_object('id', customer_id, 'deleted', true),
           updated_at = now()
       WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    await client.query(
      `UPDATE payments.payment_attempts
       SET request_payload = jsonb_build_object('redacted', true),
           response_payload = CASE WHEN response_payload IS NOT NULL THEN jsonb_build_object('redacted', true) ELSE NULL END
       WHERE merchant_id = $1 AND payment_intent_id IN (
         SELECT id FROM payments.payment_intents WHERE merchant_id = $1 AND customer_id = $2
       )`,
      [merchantId, customerId],
    );

    await client.query(
      `UPDATE payments.refunds
       SET customer_email = NULL
       WHERE merchant_id = $1 AND payment_intent_id IN (
         SELECT id FROM payments.payment_intents WHERE merchant_id = $1 AND customer_id = $2
       )`,
      [merchantId, customerId],
    );

    await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot = jsonb_build_object('id', customer_id, 'deleted', true)
       WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    // 5. Operations tables: analytics, notifications, deliveries, jobs, idempotency keys, audit logs
    await client.query(
      `DELETE FROM operations.analytics_events WHERE merchant_id = $1 AND (customer_id = $2 OR properties->>'customerId' = $2::text)`,
      [merchantId, customerId],
    );
    await client.query(`DELETE FROM operations.notification_preferences WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
    await client.query(`DELETE FROM operations.notifications WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
    await client.query(`DELETE FROM operations.email_deliveries WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
    await client.query(`DELETE FROM operations.jobs WHERE merchant_id = $1 AND payload->>'customerId' = $2::text`, [merchantId, customerId]);
    await client.query(
      `DELETE FROM operations.idempotency_keys
       WHERE merchant_id = $1 AND (response_body->>'customerId' = $2::text OR response_body->>'customer'->>'id' = $2::text)`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE platform.audit_logs
       SET metadata = jsonb_build_object('redacted', true)
       WHERE merchant_id = $1 AND (target_id = $2::text OR metadata->>'customerId' = $2::text)`,
      [merchantId, customerId],
    );
  }

  async getInvoiceObjectKeys(merchantId: string, customerId: string): Promise<string[]> {
    const result = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM payments.invoices
       WHERE merchant_id = $1 AND customer_id = $2 AND object_key IS NOT NULL`,
      [merchantId, customerId],
    );
    return result.rows.map((row) => row.object_key);
  }

  async getReceiptObjectKeys(merchantId: string, customerId: string): Promise<string[]> {
    const result = await pool.query<{ object_key: string }>(
      `SELECT d.object_key FROM operations.document_manifests d
       WHERE d.merchant_id = $1 AND (
         d.customer_id = $2 OR d.metadata->>'paymentId' IN (
           SELECT id::text FROM payments.payment_intents WHERE merchant_id = $1 AND customer_id = $2
         )
       ) AND d.document_type = 'receipt'`,
      [merchantId, customerId],
    );
    return result.rows.map((row) => row.object_key);
  }

  async getCustomerImportObjectKeys(merchantId: string): Promise<string[]> {
    const result = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM customers.customer_imports WHERE merchant_id = $1`,
      [merchantId],
    );
    return result.rows.map((row) => row.object_key);
  }

  async updateDocumentChecksum(client: pg.PoolClient, objectKey: string, checksum: string): Promise<void> {
    await client.query(
      `UPDATE operations.document_manifests
       SET checksum = $1, metadata = jsonb_set(COALESCE(metadata, '{}'::jsonb), '{anonymized}', 'true'::jsonb)
       WHERE object_key = $2`,
      [checksum, objectKey],
    );
  }

  async deleteDocumentManifest(client: pg.PoolClient, objectKey: string): Promise<void> {
    await client.query(`DELETE FROM operations.document_manifests WHERE object_key = $1`, [objectKey]);
  }

  async deleteCustomerImport(client: pg.PoolClient, objectKey: string): Promise<void> {
    await client.query(`DELETE FROM customers.customer_imports WHERE object_key = $1`, [objectKey]);
  }
}
