{"command":"create","summary":"Create ErasureWorker","path":"/workspace/source/apps/customer-service/src/erasure-worker.ts","file_text":"import { createHash, randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import { config } from '../../../packages/config/src/index.js';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { advisoryLock, transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { boundedExponentialBackoffSeconds } from '../../../packages/operations/src/retry-policy.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, ensureBucket, objectStore } from '../../../packages/storage/src/minio.js';
import { ErasureRepository, type ErasureRequestRow } from './erasure-repository.js';

async function readStream(stream: NodeJS.ReadableStream): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of stream) {
    chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
  }
  return Buffer.concat(chunks).toString('utf8');
}

export class ErasureWorker {
  private readonly workerId = `erasure-worker-${randomUUID()}`;
  private readonly redis = new Redis(config().REDIS_URL);
  private lastLeaseRecovery = 0;

  constructor(private readonly repository = new ErasureRepository()) {}

  async run(signal: AbortSignal): Promise<void> {
    while (!signal.aborted) {
      try {
        if (Date.now() - this.lastLeaseRecovery > 30_000) {
          await this.repository.recoverExpiredLeases();
          this.lastLeaseRecovery = Date.now();
        }
        const processed = await this.processOne();
        if (!processed) {
          await new Promise((resolve) => setTimeout(resolve, 250));
        }
      } catch (error) {
        logger.error({ error }, 'erasure worker loop error');
        await new Promise((resolve) => setTimeout(resolve, 1_000));
      }
    }
  }

  async trigger(): Promise<void> {
    setImmediate(() => {
      void this.processOne().catch((error) => {
        logger.error({ error }, 'error processing triggered erasure request');
      });
    });
  }

  async processOne(): Promise<boolean> {
    const request = await this.repository.claim(this.workerId);
    if (!request) return false;

    try {
      await this.executeErasure(request);
      return true;
    } catch (error) {
      logger.error({ error, requestId: request.id, customerId: request.customer_id }, 'erasure request processing failed');
      const errorCode = this.categorizeError(error);
      const delaySeconds = boundedExponentialBackoffSeconds(request.attempts + 1);
      await this.repository.markFailed(request.id, errorCode, delaySeconds);
      return true;
    }
  }

  private async executeErasure(request: ErasureRequestRow): Promise<void> {
    const { merchant_id: merchantId, customer_id: customerId } = request;

    // 1. Clean up MinIO document storage (invoices, receipts, customer imports)
    await this.cleanupStorage(merchantId, customerId);

    // 2. Clean up search index (OpenSearch) and cache/projections (Redis)
    await this.cleanupSearchAndCache(merchantId, customerId);

    // 3. Clean up database records and mark erasure request completed in a transaction
    const correlationId = randomUUID();
    await transaction(async (client) => {
      await advisoryLock(client, `erasure:${merchantId}:${customerId}`);
      await this.repository.cleanupDatabase(client, merchantId, customerId);
      await this.repository.markCompleted(client, request.id);
      await addOutboxEvent(client, {
        eventType: EVENT_TYPES.CUSTOMER_ERASED,
        aggregateType: 'customer',
        aggregateId: customerId,
        merchantId,
        correlationId,
        payload: { customerId, erasedAt: new Date().toISOString() },
      });
    });

    logger.info({ requestId: request.id, customerId }, 'customer data erasure completed');
  }

  private async cleanupStorage(merchantId: string, customerId: string): Promise<void> {
    await ensureBucket();

    // A. Sanitize Invoices in MinIO
    const invoiceKeys = await this.repository.getInvoiceObjectKeys(merchantId, customerId);
    for (const objectKey of invoiceKeys) {
      try {
        const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
        const body = await readStream(stream);
        const doc = JSON.parse(body) as Record<string, unknown>;
        doc.customer = { id: customerId, deleted: true };
        const newBody = JSON.stringify(doc);
        await objectStore.putObject(DOCUMENT_BUCKET, objectKey, newBody, Buffer.byteLength(newBody), {
          'Content-Type': 'application/json',
        });
        const checksum = createHash('sha256').update(newBody).digest('hex');
        await transaction(async (client) => {
          await this.repository.updateDocumentChecksum(client, objectKey, checksum);
        });
      } catch (error) {
        logger.warn({ error, objectKey }, 'could not sanitize invoice in object storage');
      }
    }

    // B. Sanitize Receipts in MinIO
    const receiptKeys = await this.repository.getReceiptObjectKeys(merchantId, customerId);
    for (const objectKey of receiptKeys) {
      try {
        const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
        const body = await readStream(stream);
        const doc = JSON.parse(body) as Record<string, unknown>;
        doc.customer = { id: customerId, deleted: true };
        const newBody = JSON.stringify(doc);
        await objectStore.putObject(DOCUMENT_BUCKET, objectKey, newBody, Buffer.byteLength(newBody), {
          'Content-Type': 'application/json',
        });
        const checksum = createHash('sha256').update(newBody).digest('hex');
        await transaction(async (client) => {
          await this.repository.updateDocumentChecksum(client, objectKey, checksum);
        });
      } catch (error) {
        logger.warn({ error, objectKey }, 'could not sanitize receipt in object storage');
      }
    }

    // C. Clean up Customer Imports in MinIO
    const importKeys = await this.repository.getCustomerImportObjectKeys(merchantId);
    for (const objectKey of importKeys) {
      try {
        const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
        const body = await readStream(stream);
        const parsed = JSON.parse(body) as Record<string, unknown> | Array<Record<string, unknown>>;
        if (Array.isArray(parsed)) {
          const filtered = parsed.filter((entry) => entry.customerId !== customerId && entry.id !== customerId);
          if (filtered.length !== parsed.length) {
            if (filtered.length === 0) {
              await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
              await transaction(async (client) => {
                await this.repository.deleteDocumentManifest(client, objectKey);
                await this.repository.deleteCustomerImport(client, objectKey);
              });
            } else {
              const newBody = JSON.stringify(filtered);
              await objectStore.putObject(DOCUMENT_BUCKET, objectKey, newBody, Buffer.byteLength(newBody), {
                'Content-Type': 'application/json',
              });
              const checksum = createHash('sha256').update(newBody).digest('hex');
              await transaction(async (client) => {
                await this.repository.updateDocumentChecksum(client, objectKey, checksum);
              });
            }
          }
        } else if (typeof parsed === 'object' && parsed !== null) {
          if (parsed.customerId === customerId || parsed.id === customerId) {
            await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
            await transaction(async (client) => {
              await this.repository.deleteDocumentManifest(client, objectKey);
              await this.repository.deleteCustomerImport(client, objectKey);
            });
          }
        }
      } catch (error) {
        logger.warn({ error, objectKey }, 'could not clean up customer import in object storage');
      }
    }
  }

  private async cleanupSearchAndCache(merchantId: string, customerId: string): Promise<void> {
    // A. Remove from OpenSearch
    try {
      await searchClient.delete({
        index: CUSTOMER_INDEX,
        id: `${merchantId}:${customerId}`,
        refresh: true,
      });
    } catch (error: unknown) {
      const candidate = error as { statusCode?: number; meta?: { statusCode?: number } };
      if (candidate?.statusCode !== 404 && candidate?.meta?.statusCode !== 404) {
        logger.warn({ error, customerId }, 'opensearch customer deletion warning');
      }
    }

    // B. Remove from Redis & set durable tombstone
    const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
    await this.redis.del(cacheKey);
    await this.redis.del(`${cacheKey}:activity`);
    await this.redis.set(`erased:customer:${customerId}`, '1', 'EX', 86400 * 30);
  }

  private categorizeError(error: unknown): string {
    if (error && typeof error === 'object' && 'name' in error) {
      const name = String((error as { name?: unknown }).name);
      if (name.includes('MinIO') || name.includes('S3')) return 'storage_cleanup_failed';
      if (name.includes('OpenSearch') || name.includes('Elasticsearch')) return 'search_cleanup_failed';
      if (name.includes('Redis')) return 'cache_cleanup_failed';
    }
    return 'cleanup_execution_failed';
  }
}
