{"path":"/workspace/source/scripts/privacy-check.ts","summary":"Create scripts/privacy-check.ts","command":"create","file_text":"import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import { config } from '../packages/config/src/index.js';
import { pool } from '../packages/database/src/pool.js';
import { CUSTOMER_INDEX, searchClient } from '../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../packages/storage/src/minio.js';

const gateway = process.env.GATEWAY_URL ?? 'http://localhost:3000';
const apiKey = process.env.PAYFLOW_API_KEY ?? 'pf_local_dev_northstar_4ad1539de977';
const secondApiKey = 'pf_local_dev_bluebird_924bd90d2201';

async function api<T>(
  path: string,
  method = 'GET',
  body?: unknown,
  expectedStatus = 200,
  extraHeaders: Record<string, string> = {},
  key = apiKey,
): Promise<{ status: number; data: T }> {
  const headers: Record<string, string> = { authorization: `Bearer ${key}`, ...extraHeaders };
  const init: RequestInit = { method, headers };
  if (body !== undefined) {
    headers['content-type'] = 'application/json';
    init.body = JSON.stringify(body);
  }
  const response = await fetch(`${gateway}${path}`, init);
  const data = (await response.json()) as T;
  if (response.status !== expectedStatus) {
    throw new Error(`${method} ${path} expected ${expectedStatus} but got ${response.status}: ${JSON.stringify(data)}`);
  }
  return { status: response.status, data };
}

interface ErasureResponse {
  id: string;
  customerId: string;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

console.log('--- Starting Privacy & Customer Data Deletion Checks ---');

const runId = randomUUID().slice(0, 8);
const uniqueEmail = `privacy-test-${runId}@example.test`;
const uniqueRef = `crm-privacy-${runId}`;

// 1. Create a customer
const { data: customer } = await api<{ id: string }>(
  '/v1/customers',
  'POST',
  {
    externalReference: uniqueRef,
    email: uniqueEmail,
    name: 'Privacy Test User',
    phone: '+1-555-0199',
    metadata: { test: 'privacy' },
  },
  201,
);
console.log(`Created customer: ${customer.id}`);

// 2. Add address, contact, payment method, support ticket, import, invoice, payment
await api(`/v1/customers/${customer.id}/addresses`, 'POST', {
  kind: 'billing',
  line1: '123 Privacy Blvd',
  city: 'Tech City',
  postalCode: '94000',
  country: 'US',
}, 201);

await api(`/v1/customers/${customer.id}/contacts`, 'POST', {
  kind: 'email',
  value: uniqueEmail,
  isPrimary: true,
}, 201);

const { data: method } = await api<{ id: string }>(`/v1/customers/${customer.id}/payment-methods`, 'POST', {
  providerToken: `tok_live_${randomUUID()}`,
  type: 'card',
  brand: 'visa',
  last4: '1234',
  billingName: 'Privacy Test User',
}, 201);

await api(`/v1/customers/${customer.id}/support-tickets`, 'POST', {
  subject: 'Privacy support ticket',
  body: 'My private data needs deletion later',
}, 201);

await api('/v1/customer-imports', 'POST', {
  source: 'privacy-test-crm',
  record: { customerId: customer.id, email: uniqueEmail, name: 'Privacy Test User' },
}, 201);

const { data: invoice } = await api<{ id: string; objectKey: string }>('/v1/invoices', 'POST', {
  customerId: customer.id,
  currency: 'USD',
  tax: 50,
  lines: [{ description: 'Privacy product', quantity: 1, unitAmount: 1000 }],
}, 201);

const { data: payment } = await api<{ id: string }>(
  '/v1/payments',
  'POST',
  {
    customerId: customer.id,
    paymentMethodId: method.id,
    amount: 1050,
    currency: 'USD',
    description: 'Payment for privacy user',
  },
  202,
  { 'idempotency-key': `privacy-pay-${runId}` },
);

// Wait 1 second for projections / webhooks / receipts
await new Promise((r) => setTimeout(r, 1500));

// Verify projections exist before erasure
const redis = new Redis(config().REDIS_URL);
const merchantId = '10000000-0000-4000-8000-000000000001';
const redisKey = `merchant:${merchantId}:customer:${customer.id}`;
const cached = await redis.get(redisKey);
assert.ok(cached !== null, 'Customer should be in Redis before erasure');

const opensearchDoc = await searchClient.get({ index: CUSTOMER_INDEX, id: `${merchantId}:${customer.id}` });
assert.ok(opensearchDoc.body.found, 'Customer should be in OpenSearch before erasure');

// 3. Test Invalid Idempotency Key (too short)
await api(`/v1/customers/${customer.id}/erasure-requests`, 'POST', undefined, 400, { 'idempotency-key': 'short' });

// 4. Test Non-existent customer (404)
await api(`/v1/customers/${randomUUID()}/erasure-requests`, 'POST', undefined, 404, { 'idempotency-key': `erasure-key-${runId}` });

// 5. Test Customer belonging to another merchant (404)
await api(`/v1/customers/${customer.id}/erasure-requests`, 'POST', undefined, 404, { 'idempotency-key': `erasure-key-${runId}` }, {}, secondApiKey);

// 6. Start Erasure Request
const idempotencyKey = `erasure-key-${runId}`;
const { data: erasure1 } = await api<ErasureResponse>(
  `/v1/customers/${customer.id}/erasure-requests`,
  'POST',
  undefined,
  202,
  { 'idempotency-key': idempotencyKey },
);
console.log('Erasure requested:', erasure1);
assert.equal(erasure1.customerId, customer.id);
assert.ok(erasure1.id);
assert.ok(['pending', 'processing', 'completed'].includes(erasure1.status));
assert.ok(erasure1.createdAt);
assert.ok(erasure1.updatedAt);

// 7. Idempotency test: Reusing same idempotency key for same customer returns same request
const { data: erasureReplay } = await api<ErasureResponse>(
  `/v1/customers/${customer.id}/erasure-requests`,
  'POST',
  undefined,
  202,
  { 'idempotency-key': idempotencyKey },
);
assert.equal(erasureReplay.id, erasure1.id, 'Idempotent replay must return the same request ID');

// 8. Create another dummy customer to test key conflict
const { data: secondCustomer } = await api<{ id: string }>(
  '/v1/customers',
  'POST',
  {
    externalReference: `crm-other-${runId}`,
    email: `other-${runId}@example.test`,
    name: 'Other User',
  },
  201,
);

// Reusing key for a different customer must return 409 Conflict
await api(`/v1/customers/${secondCustomer.id}/erasure-requests`, 'POST', undefined, 409, { 'idempotency-key': idempotencyKey });

// Submitting with new key for customer who already has an erasure request returns existing request
const { data: erasureNewKey } = await api<ErasureResponse>(
  `/v1/customers/${customer.id}/erasure-requests`,
  'POST',
  undefined,
  202,
  { 'idempotency-key': `different-key-${runId}` },
);
assert.equal(erasureNewKey.id, erasure1.id, 'Existing request must be returned for customer');

// 9. Poll status until completed
let finalStatus: ErasureResponse | undefined;
for (let i = 0; i < 40; i++) {
  const { data: check } = await api<ErasureResponse>(`/v1/erasure-requests/${erasure1.id}`, 'GET', undefined, 200);
  if (check.status === 'completed') {
    finalStatus = check;
    break;
  }
  await new Promise((r) => setTimeout(r, 200));
}
assert.ok(finalStatus, 'Erasure request did not reach completed state in time');
assert.equal(finalStatus.status, 'completed');
assert.ok(finalStatus.completedAt);
assert.equal(finalStatus.lastError, null);
console.log('Erasure completed:', finalStatus);

// 10. Check GET /v1/erasure-requests/:id from another merchant returns 404
await api(`/v1/erasure-requests/${erasure1.id}`, 'GET', undefined, 404, {}, secondApiKey);

// 11. Verify Customer APIs:
// GET /v1/customers/:id -> 404
await api(`/v1/customers/${customer.id}`, 'GET', undefined, 404);

// GET /v1/customers (listing) -> does not contain deleted customer
const { data: customerList } = await api<{ data: Array<{ id: string }> }>('/v1/customers', 'GET', undefined, 200);
assert.ok(!customerList.data.some((c) => c.id === customer.id), 'Deleted customer must not be listed in customer list');

// PATCH /v1/customers/:id -> 409
await api(`/v1/customers/${customer.id}`, 'PATCH', { version: 1, name: 'Hacked' }, 409);

// POST sub-resources -> 404
await api(`/v1/customers/${customer.id}/payment-methods`, 'POST', { providerToken: 'tok_test_123', type: 'card' }, 404);

// 12. Verify Redis cache & OpenSearch index are erased
const cachedAfter = await redis.get(redisKey);
assert.equal(cachedAfter, null, 'Customer should be deleted from Redis');
const activityAfter = await redis.hgetall(`${redisKey}:activity`);
assert.deepEqual(activityAfter, {}, 'Activity should be deleted from Redis');

let opensearchFound = true;
try {
  const doc = await searchClient.get({ index: CUSTOMER_INDEX, id: `${merchantId}:${customer.id}` });
  opensearchFound = doc.body.found;
} catch (e: any) {
  if (e.statusCode === 404 || e.meta?.statusCode === 404) {
    opensearchFound = false;
  }
}
assert.equal(opensearchFound, false, 'Customer should be deleted from OpenSearch');

// 13. Verify re-registering the same email and externalReference works (no unique constraint collision!)
const { data: reRegistered } = await api<{ id: string }>(
  '/v1/customers',
  'POST',
  {
    externalReference: uniqueRef,
    email: uniqueEmail,
    name: 'New Customer Same Email',
  },
  201,
);
console.log(`Re-registered new customer with same email: ${reRegistered.id}`);
assert.notEqual(reRegistered.id, customer.id);

// 14. Verify financial records retained:
// Payment still exists and has financial facts
const { data: paymentRecord } = await api<{ id: string; amount: number; currency: string }>(`/v1/payments/${payment.id}`, 'GET', undefined, 200);
assert.equal(paymentRecord.amount, 1050);

// Invoice in MinIO is sanitized
const invoiceObjStream = await objectStore.getObject(DOCUMENT_BUCKET, invoice.objectKey);
const chunks: Buffer[] = [];
for await (const chunk of invoiceObjStream) {
  chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
}
const invoiceJson = JSON.parse(Buffer.concat(chunks).toString('utf8'));
assert.equal(invoiceJson.customer.deleted, true, 'Invoice customer should be anonymized in MinIO');
assert.equal(invoiceJson.customer.email, undefined, 'Invoice customer email should not exist');

console.log('--- All Privacy & Customer Data Deletion Checks Passed Successfully! ---');

await redis.quit();
await pool.end();
"}

