{"summary":"Check existing erasure requests before checking customer table","path":"/workspace/source/apps/customer-service/src/erasure-service.ts","command":"str_replace","new_str":"  async createOrGet(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestRow> {
    const row = await transaction(async (client) => {
      await advisoryLock(client, `erasure:${merchantId}:${customerId}`);

      // 1. Reusing an idempotency key for the same customer returns the same request.
      // Reusing it for a different customer returns 409 Conflict.
      const byKey = await this.erasureRepo.findByKey(client, merchantId, idempotencyKey);
      if (byKey) {
        if (byKey.customer_id !== customerId) {
          throw Object.assign(new Error('idempotency key reused for different customer'), { statusCode: 409 });
        }
        if (byKey.status === 'failed') {
          await this.erasureRepo.resetFailedForRetry(client, byKey.id);
          byKey.status = 'pending';
        }
        return byKey;
      }

      // 2. If the customer already has a data deletion request, return that existing request instead of starting another workflow.
      const byCustomer = await this.erasureRepo.findByCustomer(client, merchantId, customerId);
      if (byCustomer) {
        if (byCustomer.status === 'failed') {
          await this.erasureRepo.resetFailedForRetry(client, byCustomer.id);
          byCustomer.status = 'pending';
        }
        return byCustomer;
      }

      // 3. Verify customer exists before creating a new request
      const customer = await this.customerRepo.findRaw(merchantId, customerId);
      if (!customer || customer.merchant_id !== merchantId) {
        throw Object.assign(new Error('customer not found'), { statusCode: 404 });
      }

      // 4. Create a new erasure request
      return await this.erasureRepo.create(client, merchantId, customerId, idempotencyKey);
    });

    await this.worker.trigger();
    return row;
  }","old_str":"  async createOrGet(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestRow> {
